  {
    "kind": "dialogue",
    "speaker_id": "17f19638-b398-45e1-8074-17befed1f719",
    "text": "Ash, does the road east stay open in rain?",
    "cited_fact_keys": ["attempt:communicate"]
  },
  {
    "kind": "narration",
    "text": "Ash responds thoughtfully, his voice steady.",
    "cited_fact_keys": ["reaction:f8bd3a7d-eb72-5c5d-a9a1-2038419e3881"]
