  {
    "kind": "dialogue",
    "speaker_id": "fbb1c051-8fb9-4dae-b800-b198c7249f3e",
    "text": "Ash responds, \"Not yet, but they should be soon.\"",
    "cited_fact_keys": ["reaction: Ash speaks to Wren about stalls' opening status"]
  },
